llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Brigatinib, which shares the methoxyaniline–aminopyrimidine core and a basic amine side chain with the query, has an absolute oral bioavailability of 46% in healthy volunteers; this high-transfer direct human measurement supports F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Nilotinib, the highest-transfer analogue, has an absolute oral bioavailability of 31% in fasted humans, supporting F ≥ 20% despite dose-dependent lower estimates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Encainide, a moderately transferable aromatic amide with a basic amine, shows ~30% oral bioavailability in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Clomipramine, a moderately transferable lipophilic basic amine drug, has ~50% oral bioavailability, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A population-PK-derived nilotinib F of 17% at 400 mg in patients illustrates dose- and solubility-limited absorption; this is a contradictory data point, but the overall nilotinib evidence and the query's more basic, solubilizing side chain favor F ≥ 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alprenolol has low absolute oral bioavailability (~15%), but its aryloxypropanolamine structure is distant from the query, so this contradictory evidence carries limited weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C55"],
      "claim": "Remimazolam has very low absolute oral bioavailability (1.2%), but as a benzodiazepine ester it is structurally dissimilar and not transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%): the strongest transferable human absolute-bioavailability data come from brigatinib (46%) and nilotinib (~30%), both aminopyrimidine-aniline kinase inhibitors; the query's basic amine side chain should improve solubility relative to nilotinib. Low-F analogues are structurally distant and lower weight.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "Nilotinib bioavailability is dose-dependent and ranges around/below 20% at higher doses, creating threshold uncertainty.",
    "First-pass metabolism or covalent-reactivity effects of the acrylamide warhead on oral bioavailability are not directly captured by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

